#!/usr/bin/env python3
"""Aggregate JSON-lines log records from stdin.

Default mode:
    per-service counts by level + each service's error rate.

--window <N><s|m|h> mode:
    counts bucketed into fixed time windows instead.

Malformed lines are counted, reported on stderr, and never crash the tool.
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from collections import defaultdict
from datetime import datetime, timezone

WINDOW_RE = re.compile(r"^(\d+)([smh])$")
WINDOW_SECONDS = {"s": 1, "m": 60, "h": 3600}
ERROR_LEVELS = {"ERROR", "CRITICAL"}


def parse_timestamp(value):
    """Return an aware UTC datetime or raise ValueError."""
    if not isinstance(value, str):
        raise ValueError("ts must be a string")
    text = value.strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def parse_window(spec):
    """Return window size in seconds or raise ValueError."""
    match = WINDOW_RE.match(spec.strip())
    if not match:
        raise ValueError(f"invalid --window {spec!r} (expected e.g. 30s, 5m, 1h)")
    return int(match.group(1)) * WINDOW_SECONDS[match.group(2)]


def parse_record(line):
    """Return {'service', 'level', 'dt'} or raise ValueError."""
    record = json.loads(line)
    if not isinstance(record, dict):
        raise ValueError("record is not a JSON object")
    service = record.get("service")
    level = record.get("level")
    if not isinstance(service, str) or not service:
        raise ValueError("missing service")
    if not isinstance(level, str) or not level:
        raise ValueError("missing level")
    dt = parse_timestamp(record.get("ts"))
    return {"service": service, "level": level, "dt": dt}


def empty_stats():
    return {"counts": defaultdict(int), "total": 0, "errors": 0}


def finalize(stats):
    out = {}
    for level in sorted(stats["counts"]):
        out[level] = stats["counts"][level]
    total = stats["total"]
    out["total"] = total
    out["errors"] = stats["errors"]
    out["error_rate"] = stats["errors"] / total if total else 0.0
    return out


def window_key(dt, window_seconds):
    epoch = int(dt.timestamp())
    start = epoch - (epoch % window_seconds)
    return (
        datetime.fromtimestamp(start, tz=timezone.utc)
        .strftime("%Y-%m-%dT%H:%M:%SZ")
    )


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--window",
        metavar="DURATION",
        help="bucket counts into windows of this duration (e.g. 5m)",
    )
    args = parser.parse_args(argv)

    window_seconds = None
    if args.window is not None:
        try:
            window_seconds = parse_window(args.window)
        except ValueError as exc:
            parser.error(str(exc))

    # stats[window_key][service] -> stats   (window mode)
    # stats[service]           -> stats     (default mode)
    stats = defaultdict(lambda: defaultdict(empty_stats))
    malformed = 0

    for lineno, raw in enumerate(sys.stdin, start=1):
        line = raw.strip()
        if not line:
            continue
        try:
            rec = parse_record(line)
        except (ValueError, json.JSONDecodeError):
            malformed += 1
            print(
                f"malformed line {lineno}: {line[:200]}",
                file=sys.stderr,
            )
            continue
        if window_seconds is None:
            stats[rec["service"]][rec["level"]] += 1
            if rec["level"] in ERROR_LEVELS:
                pass  # handled below via totals; kept for clarity
        else:
            stats[window_key(rec["dt"], window_seconds)][rec["level"]] += 1

    report = {}
    for outer_key, per_service in stats.items():
        report[outer_key] = {
            service: finalize(service_stats)
            for service, service_stats in sorted(per_service.items())
        }

    json.dump(report, sys.stdout, indent=2, sort_keys=True)
    sys.stdout.write("\n")

    if malformed:
        print(f"skipped {malformed} malformed line(s)", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

